import{_ as a,o,c as r,a2 as t}from"./chunks/framework.DXa1R37q.js";const u=JSON.parse('{"title":"Searchable operations","description":"","frontmatter":{},"headers":[],"relativePath":"searchable/operations.md","filePath":"searchable/operations.md","lastUpdated":1792947882000}'),i={name:"searchable/operations.md"};function c(s,e,n,d,l,h){return o(),r("div",null,[...e[0]||(e[0]=[t('<h1 id="searchable-operations" tabindex="-1">Searchable operations <a class="header-anchor" href="#searchable-operations" aria-label="Permalink to &quot;Searchable operations&quot;">​</a></h1><h2 id="back-up-and-restore" tabindex="-1">Back up and restore <a class="header-anchor" href="#back-up-and-restore" aria-label="Permalink to &quot;Back up and restore&quot;">​</a></h2><p>Back up <code>.neottia/searchable/</code> with the rest of the repository&#39;s canonical Neottia data. Do not depend on <code>.neottia/cache/searchable.sqlite</code>; it is derived and excluded from authority.</p><p>Restore canonical files while Searchable is stopped. Remove the cache, restart the host, and let Searchable rebuild it. If canonical validation fails, repair or restore the reported JSON file rather than editing SQLite.</p><h2 id="cache-recovery" tabindex="-1">Cache recovery <a class="header-anchor" href="#cache-recovery" aria-label="Permalink to &quot;Cache recovery&quot;">​</a></h2><p>Stop all Searchable hosts before deleting <code>.neottia/cache/searchable.sqlite</code> and its sidecars. A later <code>web_grep</code> or <code>web_ask</code> rebuilds from canonical pages according to <code>stale_policy</code>. Concurrent hosts coordinate through Repository Store leases, but one long-lived runtime per CWD is the recommended topology.</p><h2 id="rotation-and-diagnostics" tabindex="-1">Rotation and diagnostics <a class="header-anchor" href="#rotation-and-diagnostics" aria-label="Permalink to &quot;Rotation and diagnostics&quot;">​</a></h2><p>Rotate provider credentials through their source environment variables and restart the host. Diagnostics should include only the stable error code and redacted message. Query strings, page content, prompts, keys, and provider response bodies may contain secrets.</p><h2 id="failure-triage" tabindex="-1">Failure triage <a class="header-anchor" href="#failure-triage" aria-label="Permalink to &quot;Failure triage&quot;">​</a></h2><ul><li><code>CAPABILITY_DISABLED</code>: set <code>modules.searchable.enabled: true</code> in the active CWD.</li><li><code>PROVIDER_CREDENTIAL_MISSING</code>: configure the selected API provider or use DuckDuckGo.</li><li><code>NETWORK_DESTINATION_BLOCKED</code>: choose a public HTTP(S) URL; local services are intentionally unreachable through fetch.</li><li><code>STASH_CACHE_REBUILD_REQUIRED</code>: permit a rebuild or switch policy to <code>rebuild</code>.</li><li>Ollama connection errors: start Ollama and confirm the endpoint and model.</li><li><code>RESOURCE_LIMIT_EXCEEDED</code>: reduce the request or raise a reviewed limit.</li></ul><p>Call runtime <code>close()</code> on server, plugin, or session shutdown. A closed runtime does not accept new operations.</p>',11)])])}const b=a(i,[["render",c]]);export{u as __pageData,b as default};
